Here’s a clean, working **C++ program** that calculates **Simple Interest (SI)** and **Compound Interest (CI)** using **Constructor Overloading** 👇  

---

### 💻 **Program:**
```cpp
#include <iostream>
#include <cmath>
using namespace std;

class Interest {
    float principal, rate, time, amount;

public:
    // Constructor for Simple Interest
    Interest(float p, float r, float t) {
        principal = p;
        rate = r;
        time = t;
        float si = (principal * rate * time) / 100;
        cout << "\n--- Simple Interest ---" << endl;
        cout << "Principal: " << principal << endl;
        cout << "Rate: " << rate << "%" << endl;
        cout << "Time: " << time << " years" << endl;
        cout << "Simple Interest = " << si << endl;
        cout << "Total Amount = " << (principal + si) << endl;
    }

    // Constructor for Compound Interest
    Interest(float p, float r, float t, int n) {
        principal = p;
        rate = r;
        time = t;
        amount = principal * pow((1 + rate / (100 * n)), n * time);
        float ci = amount - principal;
        cout << "\n--- Compound Interest ---" << endl;
        cout << "Principal: " << principal << endl;
        cout << "Rate: " << rate << "%" << endl;
        cout << "Time: " << time << " years" << endl;
        cout << "Compound Interest = " << ci << endl;
        cout << "Total Amount = " << amount << endl;
    }
};

int main() {
    float p, r, t;
    int n;

    cout << "Enter Principal: ";
    cin >> p;
    cout << "Enter Rate of Interest (%): ";
    cin >> r;
    cout << "Enter Time (in years): ";
    cin >> t;

    // Call constructor for Simple Interest
    Interest simple(p, r, t);

    cout << "\nEnter number of times interest compounded per year: ";
    cin >> n;

    // Call constructor for Compound Interest
    Interest compound(p, r, t, n);

    return 0;
}
```

---

### 🧠 **Explanation:**
- **Constructor Overloading:**  
  Two constructors with different parameter lists handle SI and CI separately.

- **Simple Interest Formula:**  
  \[
  SI = \frac{P \times R \times T}{100}
  \]

- **Compound Interest Formula:**  
  \[
  A = P \times \left(1 + \frac{R}{100n}\right)^{nT}, \quad CI = A - P
  \]

---

### 🧩 **Sample Output:**
```
Enter Principal: 10000
Enter Rate of Interest (%): 5
Enter Time (in years): 2

--- Simple Interest ---
Principal: 10000
Rate: 5%
Time: 2 years
Simple Interest = 1000
Total Amount = 11000

Enter number of times interest compounded per year: 2

--- Compound Interest ---
Principal: 10000
Rate: 5%
Time: 2 years
Compound Interest = 1025.25
Total Amount = 11025.25
```

